def P(x, st='Body'): return Paragraph(x, s[st])
def T(headers, rows, widths):
    data = [[P(x, 'SmallBold') for x in headers]] + [[P(str(x), 'Small') for x in row] for row in rows]
    t = Table(data, colWidths=widths, repeatRows=1, hAlign='LEFT')
    t.setStyle(TableStyle([
        ('GRID',(0,0),(-1,-1),.35,colors.black), ('LINEBELOW',(0,0),(-1,0),.7,colors.black),
        ('VALIGN',(0,0),(-1,-1),'TOP'), ('LEFTPADDING',(0,0),(-1,-1),5), ('RIGHTPADDING',(0,0),(-1,-1),5),
        ('TOPPADDING',(0,0),(-1,-1),4), ('BOTTOMPADDING',(0,0),(-1,-1),4),
    ]))
    return t
def N(n, x): return P(f'{n} {x}', 'List')
def items(entries): return [N(f'{i}.', x) for i,x in enumerate(entries,1)]
def foot(c, d):
    c.saveState(); c.setStrokeColor(colors.black); c.setLineWidth(.25); c.line(1.8*cm,1.32*cm,A4[0]-1.8*cm,1.32*cm)
    c.setFont('THSarabunPSK',10); c.drawString(1.8*cm,.8*cm,'คู่มือการใช้งานและดูแลระบบเซิร์ฟเวอร์ เอกสารภายใน')
    c.drawRightString(A4[0]-1.8*cm,.8*cm,f'หน้า {d.page}'); c.restoreState()

