story += [P('6. ขั้นตอนปฏิบัติงานประจำวัน','H1'), P('6.1 ก่อนปรับปรุงระบบ ให้ตรวจสอบว่ามี backup หรือ task ทำงานอยู่หรือไม่ ตรวจพื้นที่ disk บน Host และ Guest และบันทึกเวลาที่เริ่มปฏิบัติงาน'), P('6.2 ให้สร้าง backup หรือ snapshot ที่สามารถย้อนกลับได้ก่อนอัปเดต หรือเปลี่ยน configuration ที่มีผลต่อบริการ ห้ามอัปเดต Proxmox, CloudPanel, Nginx, PHP และฐานข้อมูลพร้อมกัน'), P('6.3 ลำดับเปิดระบบหลังไฟฟ้าดับ'), *items(['เปิด Proxmox Host และรอให้ Storage กับ Network พร้อม','ตรวจ CT 102 แล้วเริ่มการทำงาน','ตรวจ CT 100 แล้วเริ่มการทำงาน','ตรวจ VM 103 แล้วตรวจบริการเว็บและ CloudPanel','เริ่ม VM 101 เมื่อจำเป็น','ทดสอบการเข้าถึงบริการภายในและภายนอกทีละบริการ']), P('6.4 ลำดับปิดเพื่อบำรุงรักษา'), *items(['แจ้งผู้ใช้งานและตรวจการสำรองข้อมูล','ปิด VM 101','ปิดเว็บหรือ VM 103 และ CT 100 ตามแผนงานที่ได้รับอนุมัติ','ปิด CT 102 หลังยืนยันว่าไม่มีการเขียนข้อมูล','ปิด Proxmox Host เป็นลำดับสุดท้าย']), P('6.5 คำสั่งตรวจสอบบน Proxmox Host','H2'), P('qm list<br/>pct list<br/>qm status 103<br/>pct status 100<br/>pct status 102<br/>df -h<br/>journalctl -p warning -b','Cmd'), PageBreak()]
story += [P('7. การสำรองข้อมูลและการกู้คืน','H1'), P('7.1 เอกสารต้นทางยังไม่ระบุปลายทาง ตารางเวลา ระยะเก็บรักษา และผลการทดสอบกู้คืนของ backup ผู้ดูแลคนถัดไปต้องตรวจสอบข้อมูลนี้ใน Proxmox และบันทึกเป็นนโยบายก่อนเริ่มรับผิดชอบระบบเต็มรูปแบบ'), P('7.2 สำหรับ SQLite ไฟล์หลักอยู่ที่ /mnt/database-backup/database.sqlite และอาจมีไฟล์ database.sqlite-wal กับ database.sqlite-shm ไฟล์เหล่านี้เกี่ยวข้องกับ transaction ที่กำลังทำงาน จึงห้ามลบหรือคัดลอกแบบไม่เข้าใจสถานะการเขียนข้อมูล'), P('7.3 ขั้นตอนสำรองข้อมูลที่ปลอดภัย'), *items(['ตรวจว่าพื้นที่ปลายทางเพียงพอและสิทธิ์การเขียนถูกต้อง','ใช้วิธี backup ที่รองรับ SQLite หรือหยุดการเขียนข้อมูลตามขั้นตอนของแอปพลิเคชัน','ตรวจความสำเร็จของไฟล์สำรอง ขนาดไฟล์ วันที่ และ checksum เมื่อมี','เก็บ backup อย่างน้อยหนึ่งชุดนอกเครื่อง Host','บันทึกผู้ดำเนินการ เวลา และผลการตรวจสอบ']), P('7.4 การกู้คืนต้องทดสอบกับ VM หรือ CT ทดสอบก่อนเสมอ ห้าม restore ทับ production โดยตรง ให้สร้าง snapshot หรือสำเนาระบบก่อนทุกครั้ง'), PageBreak()]
story += [P('8. การตรวจสอบปัญหาเบื้องต้น','H1'), T(['อาการ','ลำดับตรวจสอบ','แนวทางปฏิบัติ'],[['เข้า Proxmox ไม่ได้','Tailscale Connected หรือไม่ URL ถูกต้องหรือไม่ เปิดจาก LAN ได้หรือไม่','ตรวจสิทธิ์ Tailscale และใช้ LAN fallback เมื่อมีเหตุจำเป็น'],['CT หรือ VM หยุดทำงาน','ตรวจ status, Task log, CPU, RAM และ Disk ของ Host','อ่าน error ก่อนสั่ง Start ห้ามสั่งซ้ำโดยไม่ทราบสาเหตุ'],['เว็บไซต์เปิดไม่ได้','ตรวจ DNS, Cloudflare, Tunnel, Guest, Nginx และ Application log','แยกสาเหตุทีละชั้นและแก้เฉพาะจุด'],['CloudPanel ใช้ไม่ได้','ตรวจ VM 103, port 8443, clp-nginx และ clp-php-fpm','เข้า Console หรือ SSH และตรวจ systemctl กับ journalctl'],['SQLite ใช้ไม่ได้','ตรวจ disk, ownership, file lock, WAL SHM และ bind mount','หยุดการเขียนก่อนสำรอง ห้ามลบไฟล์ประกอบโดยพลการ'],['IP เปลี่ยน','ตรวจ DHCP lease และ ip a ใน Console','ใช้ Tailscale หรือ static IP vmbr1 เป็นข้อมูลอ้างอิง']], [3.2*cm,6.9*cm,5.9*cm]), P('8.1 คำสั่งวินิจฉัยใน Linux Guest','H2'), P('ip a<br/>ip route<br/>ping -c 3 192.168.1.1<br/>df -h<br/>free -h<br/>systemctl --failed<br/>journalctl -xe --no-pager | tail -n 80<br/>sudo ss -ltnp','Cmd'), P('8.2 ให้หยุดและขอความช่วยเหลือทันทีเมื่อพบ disk I O error, filesystem เป็น read only, ข้อมูลสูญหาย, ต้อง restore, ต้องแก้ firewall หรือ Cloudflare policy หรือไม่มั่นใจว่าคำสั่งจะลบข้อมูลหรือรีบูต Host ได้'), PageBreak()]
