story += [P('10. รายการเริ่มงานสำหรับผู้ดูแลใหม่','H1'), T(['รายการ','ผลที่ผู้ดูแลคนถัดไปต้องทำได้','ยืนยัน'],[['การเข้าถึง','ติดตั้ง Tailscale และเข้า Proxmox ด้วยบัญชีส่วนตัวได้','□'],['โครงสร้าง','อธิบายหน้าที่ Host, CT 100, CT 102, VM 103 และ VM 101 ได้','□'],['การปฏิบัติงาน','เปิด Console ดู Task log ดูทรัพยากร และเปิดปิด Guest อย่างปลอดภัยได้','□'],['CloudPanel','เข้าแผงควบคุมและตรวจ Nginx PHP MySQL ใน VM 103 ได้','□'],['ข้อมูล','ทราบตำแหน่ง SQLite และ shared bind mount','□'],['Backup','ตรวจ backup ล่าสุดและทำ restore test ในสภาพแวดล้อมทดสอบได้','□'],['ความปลอดภัย','รับ Secret ผ่าน Password Manager และ rotate รหัสเดิมแล้ว','□']], [3.2*cm,10.6*cm,2.2*cm]), P('10.1 ประเด็นที่ต้องตรวจยืนยันก่อนเริ่มดูแลระบบ','H2'), *items(['ตรวจค่า RAM จริงของ VM 103 ด้วย qm config 103 เนื่องจากเอกสารระบุทั้ง 4 GB และ 8 GB','ตรวจว่า VM 103 มีเฉพาะ 192.168.1.114/24 หรือมี net1 10.10.10.103/24 ด้วย โดยใช้ qm config 103 และ ip a ใน VM','ตรวจ IP DHCP ปัจจุบันของ CT 100 และ CT 102 และตรวจการตั้ง DHCP reservation ใน Router','ระบุปลายทาง ตารางเวลา และ retention ของ backup พร้อมผล restore test ล่าสุด','ระบุเจ้าของบัญชี Cloudflare Tailscale Domain DNS Router ISP และช่องทางกู้คืนบัญชี','รวบรวมรายชื่อเว็บไซต์ แอปพลิเคชัน Repository วิธี Deploy และเจ้าของข้อมูลของ CT 100 และ VM 103']), P('10.2 สรุป','H2'), P('ระบบมี Proxmox เป็นศูนย์กลาง Tailscale เป็นช่องทางผู้ดูแล Cloudflare Tunnel เป็นช่องทางบริการสาธารณะ CT 100 เป็นเว็บเซิร์ฟเวอร์ CT 102 เป็นที่เก็บ SQLite และข้อมูลสำรอง VM 103 เป็น CloudPanel และ VM 101 เป็น Windows สำหรับงานทั่วไป การเริ่มดูแลระบบอย่างปลอดภัยต้องยืนยันค่าที่ขัดกัน ทดสอบ backup และ rotate ข้อมูลลับทุกชุดก่อนผู้ดูแลคนถัดไปรับผิดชอบเต็มรูปแบบ')]

